<?php get_header(); the_post(); $q=kzfr_filter_value('q'); $program=kzfr_filter_value('program'); $genre=kzfr_filter_value('genre'); $date=kzfr_filter_value('date'); $args=['s'=>$q,'meta_key'=>'kzfr_broadcast_date','orderby'=>'meta_value','order'=>'DESC']; $meta=[]; if($program)$meta[]=['key'=>'kzfr_program_slug','value'=>$program]; if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$meta[]=['key'=>'kzfr_broadcast_date','value'=>$date,'compare'=>'LIKE']; if($meta)$args['meta_query']=$meta; if($genre)$args['tax_query']=[['taxonomy'=>'kzfr_genre','field'=>'slug','terms'=>$genre]]; $broadcasts=kzfr_query('kzfr_broadcast',-1,$args); ?>
<div class="section-wrap section-space"><?php kzfr_page_intro('PAST BROADCASTS','Archives','Find and play a recording by program, date, or category.'); ?><form class="filter-bar archive-filters" method="get" role="search"><input type="hidden" name="design" value="<?php echo esc_attr(kzfr_current_design()); ?>"><div class="field field-grow"><label for="archive-search">Search broadcasts</label><input id="archive-search" type="search" name="q" value="<?php echo esc_attr($q); ?>" placeholder="Program or keyword"></div><div class="field"><label for="archive-program">Program</label><select id="archive-program" name="program"><option value="">All programs</option><?php $programs=kzfr_query('kzfr_program'); foreach($programs->posts as $p): ?><option value="<?php echo esc_attr($p->post_name); ?>" <?php selected($program,$p->post_name); ?>><?php echo esc_html($p->post_title); ?></option><?php endforeach; ?></select></div><div class="field"><label for="archive-genre">Category</label><select id="archive-genre" name="genre"><option value="">All categories</option><?php foreach(get_terms(['taxonomy'=>'kzfr_genre','hide_empty'=>true]) as $term): ?><option value="<?php echo esc_attr($term->slug); ?>" <?php selected($genre,$term->slug); ?>><?php echo esc_html($term->name); ?></option><?php endforeach; ?></select></div><div class="field"><label for="archive-date">Broadcast date</label><input type="date" id="archive-date" name="date" value="<?php echo esc_attr($date); ?>"></div><button class="button button-dark" type="submit">Search</button><a class="text-link" href="<?php echo kzfr_url('archives'); ?>">Reset</a></form><p class="result-count" role="status"><?php echo esc_html($broadcasts->found_posts.' '.((int)$broadcasts->found_posts===1 ? 'recording found' : 'recordings found')); ?></p><div class="archive-list"><?php while($broadcasts->have_posts()): $broadcasts->the_post(); ?><article class="broadcast-row"><span class="broadcast-icon" aria-hidden="true">◎</span><div><p class="eyebrow"><?php echo esc_html(kzfr_meta('broadcast_date')); ?> · <?php echo esc_html(kzfr_genre()); ?></p><h2><?php echo esc_html(get_the_title()); ?></h2></div><div class="broadcast-actions"><?php kzfr_recording_button(); kzfr_link(kzfr_meta('source_url'),'Recording page','text-link'); ?></div></article><?php endwhile; wp_reset_postdata(); ?></div><?php if(!$broadcasts->found_posts): ?><div class="empty-state"><h2>No recordings match.</h2><p>Try fewer filters or <a href="<?php echo esc_url(kzfr_station('archive_url','https://kzfr.studio.creek.org/archives/')); ?>">browse the complete official archive</a>.</p></div><?php endif; ?><div class="prose"><?php the_content(); ?></div></div><?php get_footer(); ?>
